"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc} from '@/lib/pilot';
import {retainCashierVariancePosting,restoreCashierVariancePosting,readCashierVariancePostingReceipt,readCashierVariancePostingStatus,clearCashierVariancePosting,type CashierVariancePostingSelection,type CashierVariancePostingRequest} from '@/lib/cashier-variance-posting';
import type {HandoffScope} from '@/lib/cashier-handoff';
export function CashierVariancePostingAction({scope,session,selection,preview,onPending}:{scope:HandoffScope;session:string;selection:CashierVariancePostingSelection|null;preview:Record<string,unknown>|null;onPending:(value:boolean)=>void}){
 const [pending,setPending]=useState<CashierVariancePostingRequest|null>(null),[ready,setReady]=useState(false),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[done,setDone]=useState(false);const alive=useRef(false),lock=useRef(false),notify=useRef(onPending);notify.current=onPending;
 useEffect(()=>{alive.current=true;try{const r=restoreCashierVariancePosting(sessionStorage,scope,session);setPending(r);notify.current(!!r);setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to recover saved cash variance.');notify.current(true)}return()=>{alive.current=false}},[]);
 useEffect(()=>{setConfirmed(false)},[preview]);
 async function run(kind:'post'|'check'|'cancel'){if(lock.current||!ready||done||(kind==='post'&&!confirmed)||(kind==='cancel'&&!cancelConfirmed))return;lock.current=true;setBusy(true);setError('');setMessage('');let request=pending;
 try{const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen bank reconciliation.');
 if(!request){if(kind!=='post'||!selection||!preview)throw Error('Prepare a cash variance preview first.');request={id:crypto.randomUUID(),selection,review:preview};retainCashierVariancePosting(sessionStorage,request);setPending(request);notify.current(true)}
 const args={p_tenant:scope.tenant,p_property:scope.property,p_request:request.id};
 if(kind==='post')readCashierVariancePostingReceipt(await hotelRpc('post_cashier_variance',{...args,p_review:request.review,p_confirmed:true}),request);
 if(kind==='cancel')await hotelRpc('cancel_cashier_variance_posting',{...args,p_confirmed:true});
 const status=await hotelRpc('cashier_variance_posting_status',args),parsed=readCashierVariancePostingStatus(status,request);
 const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Recover the saved cash variance after signing back in.');
 if(parsed.state!=='missing'){clearCashierVariancePosting(sessionStorage,request,status);if(alive.current){setPending(null);setDone(parsed.state==='posted');setConfirmed(false);setCancelConfirmed(false);notify.current(false);setMessage(parsed.state==='cancelled'?'Variance request cancelled. Prepare a fresh preview.':parsed.reversed?'Variance was posted and subsequently reversed.':'Cash variance posted. This records the difference; it does not recover cash.')}}else if(alive.current)setMessage('No posting found. Retry the saved request or cancel it.');
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to complete cash variance. Check the saved request before retrying.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section aria-label="Post cash variance">{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}{!done&&<><label><input type="checkbox" disabled={busy||!ready||(!pending&&!preview)} checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I approve this cash variance to the ledger.</label><button type="button" disabled={busy||!ready||!confirmed||(!pending&&!preview)} onClick={()=>void run('post')}>{pending?'Retry saved cash variance':'Post cash variance'}</button>{pending&&<><p>Saved cash variance request: {pending.id}</p><button type="button" disabled={busy} onClick={()=>void run('check')}>Check cash variance outcome</button><label><input type="checkbox" disabled={busy} checked={cancelConfirmed} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this request if it has not posted.</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel unposted cash variance</button></>}</>}</section>
}
